<script setup lang="ts">import { onMounted, ref } from "vue"; import { useRouter } from "vue-router"; import { createPayment, listRepairs, type Payment } from "../api"; const router = useRouter(); const repairs = ref<{ id: string; brand: string; model: string }[]>([]); const form = ref<{ repairOrderId: string; amountCents: number; method: Payment["method"]; reference: string }>({ repairOrderId: "", amountCents: 0, method: "card", reference: "" }); const error = ref(""); onMounted(async () => { repairs.value = await listRepairs(); }); async function save() { try { const payment = await createPayment(form.value); void router.push({ name: "payments.detail", params: { id: payment.id } }); } catch (reason) { error.value = (reason as Error).message; } }</script><template><form class="entity-form" @submit.prevent="save"><header><div><p class="eyebrow">TPV</p><h1>Registrar cobro</h1></div></header><fieldset><legend>Datos del cobro</legend><label>Reparacion<select v-model="form.repairOrderId" required><option disabled value="">Selecciona una orden</option><option v-for="repair in repairs" :key="repair.id" :value="repair.id">{{ repair.brand }} {{ repair.model }}</option></select></label><label>Importe (centimos)<input v-model.number="form.amountCents" type="number" min="1" required /></label><label>Metodo<select v-model="form.method"><option value="cash">Efectivo</option><option value="card">Tarjeta</option><option value="transfer">Transferencia</option></select></label><label>Referencia<input v-model="form.reference" /></label></fieldset><p v-if="error" class="feedback error">{{ error }}</p><footer><button class="secondary" type="button" @click="router.back()">Cancelar</button><button>Registrar cobro</button></footer></form></template>